package in.foodcart.data; import org.springframework.data.mongodb.repository.MongoRepository; import java.util.*; public interface OrderRepository extends MongoRepository<OrderEntity,String>{List<OrderEntity> findByVendorIdOrderByCreatedAtDesc(String vendorId);List<OrderEntity> findByCustomerIdOrderByCreatedAtDesc(String customerId);Optional<OrderEntity> findByIdAndVendorId(String id,String vendorId);}
